contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries a withdrawAll call with provided callerIsOwner and amount pre-funded to c
    // params:
    //  - ownerAddr: the address that was used to deploy c.owner (must match c.owner to allow succeed)
    //  - recipient: address to receive withdrawal
    //  - amount: Ether to first send into c (funding)
    //  - callFromOwner: if true, this contract will act as owner by assuming ownerAddr equals address(this)
    // Note: deployment environment deploys c fresh, so owner was set at c's constructor; we pass ownerAddr to relate to c.owner getter
    function run(address ownerAddr, address payable recipient, uint256 amount, bool callFromOwner) public payable {
        require(address(this).balance >= amount);
        // Fund contract c with `amount` wei
        // Send Ether to c using fallback
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;
        address ownerBefore = c.owner();

        // Decide who will invoke withdrawAll: if callFromOwner is true, we require that ownerAddr equals address(this)
        // so that this contract is the owner and the call should succeed; otherwise the call should revert.
        // We don't change msg.sender here; the call will originate from this contract.
        // Ensure internal consistency: if callFromOwner==true then ownerAddr must equal address(this).
        require(callFromOwner ? ownerAddr == address(this) : true);
        // Also ensure provided ownerAddr matches observed owner to connect parameter to contract state
        // (this is not required but makes the rule relate the parameter to c.owner())
        require(ownerAddr == ownerBefore);

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule:
        // If the caller (this contract) is the owner recorded in c, the call must not revert,
        // and all Ether previously in c transfers to the recipient (c balance 0 and recipient increased by that amount).
        // If the caller is not the owner, the call must revert and balances remain unchanged.
        assert(
            (ownerBefore == address(this) && !reverted && afterC == 0 && afterRecipient == beforeRecipient + beforeC)
            || (ownerBefore != address(this) && reverted && afterC == beforeC && afterRecipient == beforeRecipient)
        );
    }

    receive() external payable {}
}

