        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after attempt
        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // If withdrawAll did not revert then it must have transferred the entire prior balance of c to recipient leaving c with zero balance
        assert(reverted || (afterC == 0 && afterRecipient == beforeRecipient + beforeC));
