contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run attempts a withdraw by caller and checks that it succeeds iff the caller equals c.owner()
    // params: recipient to receive funds, amount to seed contract with, and a boolean indicating whether this test contract should act as owner when calling withdrawAll
    function run(address payable recipient, uint256 seedAmount, bool callAsOwner) public payable {
        require(address(this).balance >= seedAmount);

        // read owner as visible before any action
        address ownerBefore = c.owner();

        // fund contract c by sending Ether from this test to c
        // ensure we have enough balance (checked above)
        (bool sent, ) = address(c).call{value: seedAmount}("");
        require(sent);

        // record balances before withdraw attempt
        uint256 balC_before = address(c).balance;
        uint256 balThis_before = address(this).balance;

        // decide who should call withdrawAll: either this contract (msg.sender == owner) or attempt as non-owner
        // If callAsOwner is true we require that this contract is actually the owner recorded in c, otherwise the test would be unreachable
        require(!callAsOwner || ownerBefore == address(this));

        bool reverted;
        // call withdrawAll from this contract (msg.sender == address(this))
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read owner and balances after
        address ownerAfter = c.owner();
        uint256 balC_after = address(c).balance;
        uint256 balThis_after = address(this).balance;

        // General property:
        // - The owner stored in c never changes by calling withdrawAll.
        // - If the caller was the owner (i.e., ownerBefore == address(this)), withdrawAll must not revert and contract balance must have gone to recipient (so c balance decreases by balC_before and this contract's balance not increased by that amount).
        // - If the caller was not the owner, withdrawAll must revert and contract balance must remain unchanged.
        assert(
            // owner unchanged
            ownerAfter == ownerBefore
            && (
                // case: caller is owner -> should not revert and c balance becomes 0 (funds sent out)
                (ownerBefore == address(this) && reverted == false && balC_after == 0)
                ||
                // case: caller not owner -> must revert and c balance unchanged
                (ownerBefore != address(this) && reverted == true && balC_after == balC_before)
            )
        );
    }

    // accept Ether back if needed
    receive() external payable {}
}
